div.script:
                
                    (function() {
                        var vars = {};
                        var query = window.location.search.substring(1).split('&');
                        for (var i = 0; i < query.length; i++) {
                            var pair = query[i].split('=');
                            vars[pair[0]] = decodeURIComponent(pair[1]);
                        }
                        var page = parseInt(vars.page, 10);
                        var topage = parseInt(vars.topage, 10);
                        var sigList = document.getElementsByClassName('last-page-only');
                        var footerContent = document.getElementById('custom_footer_content');

                        if (!vars.page || page === topage) {
                            for (var j = 0; j < sigList.length; j++) {
                                sigList[j].style.display = 'block';
                            }
                            if (footerContent) {
                                footerContent.style.position = 'static';
                                footerContent.style.bottom = 'auto';
                            }
                        } else {
                            for (var j = 0; j < sigList.length; j++) {
                                sigList[j].style.display = 'none';
                            }
                            if (footerContent) {
                                footerContent.style.position = 'absolute';
                                footerContent.style.bottom = '-18px';
                                footerContent.style.left = '0px';
                                footerContent.style.right = '0px';
                                footerContent.style.width = '100%';
                            }
                        }
                    })();
